styles:
.b-press-outlets { margin: 2em 0; }
.b-press-outlets__title { margin: 0 0 1em; font-size: 1.5em; }
.b-press-outlets__group + .b-press-outlets__group { margin-top: 2em; }
.b-press-outlets__kind { margin: 0 0 0.75em; font-size: 1.15em; }
.b-press-outlets__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(12em, 1fr)); gap: 1em; margin: 0; padding: 0; list-style: none; }
.b-press-outlets__card { display: flex; flex-direction: column; gap: 0.5em; padding: 1em; border: 1px solid color-mix(in srgb, currentColor 15%, transparent); border-radius: 0.5em; }
.b-press-outlets__link { display: flex; flex-direction: column; gap: 0.75em; color: inherit; text-decoration: none; }
.b-press-outlets__link:hover .b-press-outlets__name { text-decoration: underline; }
.b-press-outlets__logo { display: block; max-width: 100%; max-height: 3em; width: auto; height: auto; }
.b-press-outlets__name { font-weight: 600; }
.b-press-outlets__summary { margin: 0; font-size: 0.9em; opacity: 0.8; }
